SELECT CASE WHEN duration_sec >= 454 THEN 'high' WHEN duration_sec >= 82 THEN 'mid' ELSE 'low' END duration_sec_bucket, SUM(duration_sec) total_duration_sec, COUNT(*) cnt, ROUND(SUM(duration_sec) * 100.0 / SUM(SUM(duration_sec)) OVER (), 2) AS pct_of_total FROM web_events GROUP BY CASE WHEN duration_sec >= 454 THEN 'high' WHEN duration_sec >= 82 THEN 'mid' ELSE 'low' END ORDER BY pct_of_total DESC
